    status: 201,
    errors: ["VALIDATION_FAILED","STOCK_ITEM_ARCHIVED","CONFLICT","SERVICE_MANAGED"],
    events: ["inventory.stock.changed","inventory.adjustment.recorded","inventory.stock.low"],
